<script setup lang="ts">import {onMounted,ref} from 'vue';import {clone,getStudio,saveStudio,type StudioPayload} from './content-studio-api';const payload=ref<StudioPayload|null>(null),message=ref('');onMounted(async()=>payload.value=await getStudio());async function save(){const doc=clone(payload.value!.document);await saveStudio(payload.value!,doc,'site-settings','global','修改网站公共设置');message.value='网站设置草稿已保存。';payload.value=await getStudio()}</script>
<template><div v-if="payload" class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">网站设置</p><h1>公共品牌与联系方式</h1><p>只有明确填写并发布的公开联系方式才会进入网站。</p></div></div><p v-if="message" class="inline-message">{{message}}</p><section><div class="form-grid"><label>中文品牌<input v-model="payload.document.siteSettings.brand.zh"></label><label>英文品牌<input v-model="payload.document.siteSettings.brand.en"></label><label>公开联系邮箱<input v-model="payload.document.siteSettings.contactEmail" type="email" placeholder="留空则不公开"></label><label class="wide">中文 Footer 说明<textarea v-model="payload.document.siteSettings.footerNote.zh"></textarea></label><label class="wide">English footer note<textarea v-model="payload.document.siteSettings.footerNote.en"></textarea></label></div></section><section><h2>数据备份</h2><div class="workspace-actions"><a class="button quiet" href="/api/admin/content-studio/export.json">导出全部内容 JSON</a><a class="button quiet" href="/api/admin/content-studio/export.geojson">导出地点 GeoJSON</a></div></section><div class="editor-action-bar"><button class="primary-action" @click="save">保存设置草稿</button></div></div></template>
